  <dl class="intimation-card__details"><div><dt>Sample type</dt><dd>{r.profile.sample_type||'Not entered'}</dd></div><div><dt>Required date</dt><dd>{date(r.profile.buyer_required_date)}</dd></div><div class="intimation-card__sizes"><dt>Size · colour · quantity</dt><dd>{#each r.variants||[] as v}<span>{v.size||'Size pending'} · {v.colour||'Colour pending'} <b>× {v.quantity}</b></span>{/each}</dd></div></dl>
  <div class="intimation-card__mail"><div class="intimation-card__mail-title"><Mail size={18}/><div><span>Buyer mail</span><p>{r.profile.email_subject||'No subject provided'}</p></div></div>{#if r.profile.email_message}<button type="button" class="button secondary" disabled={busy} onclick={()=>onMail(r)}>Read mail</button>{:else}<span class="intimation-card__muted">No pasted message</span>{/if}</div>
  <footer class="intimation-card__footer"><div class="intimation-card__files">{#each r.files||[] as file}<button type="button" class="attachment" disabled={busy} onclick={()=>onPreview(file)}><Paperclip size={15}/><span>Preview {file.name}</span></button>{:else}<span class="intimation-card__muted">No attachments</span>{/each}</div>{#if canEdit&&['Draft','Changes requested'].includes(r.status)}<button type="button" class="button primary" disabled={busy} onclick={()=>onGenerate(r)}>Generate sample indent <ArrowRight size={16}/></button>{:else}<button type="button" class="button secondary" disabled={busy} onclick={()=>onOpen(r.id)}>View request <ArrowRight size={16}/></button>{/if}</footer>
 </article>{:else}<div class="queue-empty"><h4>All caught up</h4><p>New intimations will appear here with their sample details and buyer instructions.</p></div>{/each}</div>
</section>
